// Test-only input reconstruction appended in this private implementation module.
// Copy only serde-skipped state generated by the exact original source API
// replay. Preserve every deserialized initial field, including ordered queues.
// This method is called before stepping, never by the production pipeline.
impl ImpulseJointSet {
    pub fn scene_probe_restore_pending_journal(&mut self, replayed: &Self) {
        self.island_events = replayed.island_events.clone();
        self.modified_joints = replayed.modified_joints.clone();
        self.all_joints_modified = replayed.all_joints_modified;
        self.assembly_epoch = replayed.assembly_epoch;
        self.selection_epochs = replayed.selection_epochs;
    }
}
